var APTV_DEFAULT_SOURCE_URL =
  "https://raw.githubusercontent.com/Kimentanm/aptv/master/m3u/iptv.m3u";
var APTV_DEFAULT_USER_AGENT = "AptvPlayer-UA";
var APTV_COVER_CCTV = "data:image/png;base64,";
var APTV_COVER_4K = "data:image/png;base64,";
var APTV_COVER_GALA = "data:image/png;base64,";
var APTV_COVER_SATELLITE = "data:image/png;base64,";
var APTV_COVER_DEFAULT = "data:image/png;base64,";
var APTV_LINK_PREFIX = "aptv://";
var APTV_CACHE_MS = 300000;
var APTV_PAGE_SIZE = 40;
var APTV_SEARCH_PAGE_SIZE = 30;
var aptvPlaySequence = 0;
var aptvState = {
  sourceURL: "",
  defaultUserAgent: "",
  loadedAt: 0,
  channels: [],
  meta: {},
  promise: null,
  promiseKey: ""
};

function aptvText(value) {
  return value === null || value === undefined ? "" : String(value).trim();
}

function aptvDecodeEntities(value) {
  return aptvText(value)
    .replace(/&#x([0-9a-f]+);/gi, function (_, hex) {
      return String.fromCharCode(parseInt(hex, 16));
    })
    .replace(/&#(\d+);/g, function (_, number) {
      return String.fromCharCode(parseInt(number, 10));
    })
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&amp;/gi, "&");
}

function aptvConfiguredSourceURL(params) {
  params = params || {};
  var url =
    aptvText(params.source_url) ||
    aptvState.sourceURL ||
    APTV_DEFAULT_SOURCE_URL;
  if (!/^https?:\/\/[^\s]+$/i.test(url)) {
    throw new Error("M3U 地址必须是 HTTP(S) 完整地址");
  }
  return url;
}

function aptvConfiguredDefaultUA(params) {
  params = params || {};
  return (
    aptvText(params.default_user_agent) ||
    aptvState.defaultUserAgent ||
    APTV_DEFAULT_USER_AGENT
  );
}

function aptvConfiguredTimeout(params) {
  var value = parseInt(
    aptvText(params && params.request_timeout) || "20000",
    10
  );
  if (!isFinite(value)) value = 20000;
  return Math.max(5000, Math.min(60000, value));
}

function aptvResponseStatus(response) {
  return Number(
    (response && (response.statusCode || response.status || response.code)) || 200
  );
}

function aptvResponseText(response) {
  var status = aptvResponseStatus(response);
  if (status < 200 || status >= 300) throw new Error("HTTP " + status);
  var data = response && response.data !== undefined ? response.data : response;
  if (typeof data === "string") return data;
  if (data === null || data === undefined) return "";
  return JSON.stringify(data);
}

function aptvAttrs(line) {
  var attrs = {};
  var pattern =
    /([A-Za-z0-9_-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s,]+))/g;
  var match;
  while ((match = pattern.exec(aptvText(line)))) {
    attrs[match[1].toLowerCase()] = aptvDecodeEntities(
      match[2] || match[3] || match[4] || ""
    );
  }
  return attrs;
}

function aptvCommaOutsideQuotes(line) {
  var quoted = false;
  var quote = "";
  var value = aptvText(line);
  for (var index = 0; index < value.length; index += 1) {
    var char = value.charAt(index);
    if (
      (char === '"' || char === "'") &&
      (index === 0 || value.charAt(index - 1) !== "\\")
    ) {
      if (!quoted) {
        quoted = true;
        quote = char;
      } else if (char === quote) {
        quoted = false;
        quote = "";
      }
    } else if (char === "," && !quoted) {
      return index;
    }
  }
  return -1;
}

function aptvExtinfTitle(line) {
  var comma = aptvCommaOutsideQuotes(line);
  return comma >= 0 ? aptvText(line.slice(comma + 1)) : "";
}

function aptvNormalizeReferer(value) {
  var referer = aptvText(value);
  if (/^https?:\/[^\/]/i.test(referer)) {
    referer = referer.replace(/^(https?:)\//i, "$1//");
  }
  return /^https?:\/\/[^\s]+$/i.test(referer) ? referer : "";
}

function aptvPlaylistHeaderHeaders(value) {
  var headers = {};
  aptvText(value)
    .split(/[|&;]/)
    .forEach(function (entry) {
      var equal = entry.indexOf("=");
      if (equal <= 0) return;
      var name = aptvText(entry.slice(0, equal));
      var headerValue = aptvText(entry.slice(equal + 1));
      if (/^referer$/i.test(name)) headers.Referer = headerValue;
      if (/^user-agent$/i.test(name)) headers["User-Agent"] = headerValue;
    });
  return headers;
}

function aptvChannelKey(group, tvgId, tvgName, title) {
  return encodeURIComponent(
    [group || "未分组", tvgId, tvgName, title].join("|")
  );
}

function aptvParsePlaylist(text) {
  var source = aptvText(text).replace(/^\uFEFF/, "").replace(/\r/g, "");
  if (source.indexOf("#EXTM3U") !== 0) {
    throw new Error("直播源不是有效的 M3U 文件");
  }

  var lines = source.split("\n");
  var firstLine = lines[0] || "";
  var rootAttrs = aptvAttrs(firstLine);
  var meta = {
    epgURLs: aptvText(rootAttrs["x-tvg-url"])
      .split(",")
      .map(function (item) {
        return aptvText(item);
      })
      .filter(Boolean),
    catchup: aptvText(rootAttrs.catchup),
    catchupSource: aptvText(rootAttrs["catchup-source"])
  };
  var channels = [];
  var keyCounts = {};
  var pending = null;
  var currentGroup = "";

  function addChannel(url) {
    if (!pending) return;
    if (!/^(?:https?|rtmp|rtsp):\/\//i.test(url)) {
      pending = null;
      return;
    }

    var title = aptvText(pending.title || pending.name) ||
      "频道" + (channels.length + 1);
    var group = aptvText(pending.group || currentGroup) || "未分组";
    var baseKey = aptvChannelKey(
      group,
      pending.tvgId,
      pending.name,
      title
    );
    var occurrence = keyCounts[baseKey] || 0;
    keyCounts[baseKey] = occurrence + 1;
    var key = occurrence ? baseKey + "~" + occurrence : baseKey;
    var extraHeaders = aptvPlaylistHeaderHeaders(pending.httpHeader);
    var referer = aptvNormalizeReferer(
      pending.referer || extraHeaders.Referer
    );

    channels.push({
      index: channels.length,
      key: key,
      title: title,
      name: aptvText(pending.name) || title,
      group: group,
      tvgId: aptvText(pending.tvgId),
      logo: aptvText(pending.logo),
      url: url,
      userAgent: aptvText(
        pending.userAgent ||
        extraHeaders["User-Agent"] ||
        rootAttrs["http-user-agent"]
      ),
      referer: referer,
      duration: pending.duration,
      catchup: aptvText(pending.catchup || meta.catchup),
      catchupSource: aptvText(
        pending.catchupSource || meta.catchupSource
      )
    });
    pending = null;
  }

  lines.forEach(function (rawLine) {
    var line = aptvText(rawLine);
    if (!line) return;
    if (/^#EXTINF:/i.test(line)) {
      var attrs = aptvAttrs(line);
      var comma = aptvCommaOutsideQuotes(line);
      pending = {
        title: aptvExtinfTitle(line),
        name: attrs["tvg-name"] || "",
        group: attrs["group-title"] || "",
        tvgId: attrs["tvg-id"] || "",
        logo: attrs["tvg-logo"] || "",
        duration: comma >= 5 ? line.slice(8, comma) : "",
        userAgent:
          attrs["http-user-agent"] ||
          attrs["user-agent"] ||
          "",
        referer: attrs["http-referer"] || "",
        httpHeader: attrs["http-header"] || "",
        catchup: attrs.catchup || "",
        catchupSource: attrs["catchup-source"] || ""
      };
      return;
    }
    if (/^#EXTGRP:/i.test(line)) {
      currentGroup = aptvText(line.slice(8));
      if (pending && !pending.group) pending.group = currentGroup;
      return;
    }
    if (/^#EXTVLCOPT:/i.test(line)) {
      if (pending) {
        var option = line.slice(11);
        var userAgent = option.match(/^http-user-agent=(.+)$/i);
        if (userAgent) pending.userAgent = aptvText(userAgent[1]);
      }
      return;
    }
    if (line.charAt(0) === "#") return;
    addChannel(line);
  });

  if (!channels.length) throw new Error("M3U 中没有可播放条目");
  return { channels: channels, meta: meta };
}

async function aptvLoadPlaylist(params) {
  params = params || {};
  var sourceURL = aptvConfiguredSourceURL(params);
  var defaultUserAgent = aptvConfiguredDefaultUA(params);
  var now = Date.now();
  if (
    aptvState.channels.length &&
    aptvState.sourceURL === sourceURL &&
    aptvState.defaultUserAgent === defaultUserAgent &&
    now - aptvState.loadedAt < APTV_CACHE_MS
  ) {
    return {
      channels: aptvState.channels,
      meta: aptvState.meta
    };
  }

  var promiseKey = sourceURL + "|" + defaultUserAgent;
  if (aptvState.promise && aptvState.promiseKey === promiseKey) {
    return aptvState.promise;
  }

  aptvState.promiseKey = promiseKey;
  aptvState.promise = (async function () {
    var response = await Widget.http.get(sourceURL, {
      headers: { "User-Agent": defaultUserAgent },
      timeout: aptvConfiguredTimeout(params)
    });
    var parsed = aptvParsePlaylist(aptvResponseText(response));
    aptvState.sourceURL = sourceURL;
    aptvState.defaultUserAgent = defaultUserAgent;
    aptvState.loadedAt = Date.now();
    aptvState.channels = parsed.channels;
    aptvState.meta = parsed.meta;
    return parsed;
  })();

  try {
    return await aptvState.promise;
  } finally {
    aptvState.promise = null;
    aptvState.promiseKey = "";
  }
}

function aptvCover(group, title) {
  return aptvProxiedCover(
    aptvGroupLogoSource(group),
    group,
    600,
    900
  );
}

function aptvBackdrop(group) {
  return aptvProxiedCover(
    aptvGroupLogoSource(group),
    group,
    1280,
    720
  );
}

function aptvGroupLogoSource(group) {
  var keys = {
    "央视IPV4": "CCTV1",
    "卫视IPV4": "湖南卫视",
    "4K8K频道": "CCTV4K",
    "历年春晚": "CCTV1"
  };
  var key = keys[group] || "CCTV1";
  return (
    "https://cdn.jsdelivr.net/gh/fanmingming/live@main/tv/" +
    encodeURIComponent(key) +
    ".png"
  );
}

function aptvChannelCover(channel) {
  return aptvProxiedCover(
    aptvChannelLogoSource(channel),
    channel.group,
    600,
    900
  );
}

function aptvChannelBackdrop(channel) {
  return aptvProxiedCover(
    aptvChannelLogoSource(channel),
    channel.group,
    1280,
    720
  );
}

function aptvChannelLogoSource(channel) {
  if (channel.logo) return channel.logo;
  var key =
    channel.tvgId ||
    channel.name ||
    channel.title ||
    (channel.group === "历年春晚" ? "CCTV1" : "");
  if (!key || channel.group === "历年春晚") key = "CCTV1";
  return (
    "https://cdn.jsdelivr.net/gh/fanmingming/live@main/tv/" +
    encodeURIComponent(key) +
    ".png"
  );
}

function aptvCoverBackground(group) {
  var colors = {
    "央视IPV4": "4b0f19",
    "卫视IPV4": "0a2c4b",
    "4K8K频道": "2a1750",
    "历年春晚": "4c1b0f"
  };
  return colors[group] || "0b3a37";
}

function aptvProxiedCover(sourceURL, group, width, height) {
  return (
    "https://wsrv.nl/?url=" +
    encodeURIComponent(sourceURL) +
    "&w=" + width +
    "&h=" + height +
    "&fit=contain&cbg=" + aptvCoverBackground(group) +
    "&output=png"
  );
}

function aptvGroupPriority(group) {
  var priorities = {
    "央视IPV4": 10,
    "卫视IPV4": 20,
    "4K8K频道": 30,
    "历年春晚": 40
  };
  return priorities[group] || 500;
}

function aptvGroupsFromChannels(channels) {
  var map = {};
  var groups = [];
  channels.forEach(function (channel) {
    if (!map[channel.group]) {
      map[channel.group] = {
        name: channel.group,
        channels: [],
        firstIndex: channel.index
      };
      groups.push(map[channel.group]);
    }
    map[channel.group].channels.push(channel);
  });
  groups.sort(function (left, right) {
    return (
      aptvGroupPriority(left.name) - aptvGroupPriority(right.name) ||
      left.firstIndex - right.firstIndex
    );
  });
  return groups;
}

function aptvGenreId(group) {
  return "aptv-group:" + encodeURIComponent(group);
}

function aptvGroupFromGenre(genreId) {
  var value = aptvText(genreId);
  if (value.indexOf("aptv-group:") !== 0) return "";
  var encoded = value.slice("aptv-group:".length);
  try {
    return decodeURIComponent(encoded);
  } catch (error) {
    return "";
  }
}

function aptvNextPlayNonce() {
  aptvPlaySequence += 1;
  return Date.now().toString(36) +
    "-" +
    aptvPlaySequence.toString(36);
}

function aptvChannelLink(key) {
  return (
    APTV_LINK_PREFIX +
    "channel/" +
    key +
    "?play=" +
    aptvNextPlayNonce()
  );
}

function aptvGroupLink(group) {
  return (
    APTV_LINK_PREFIX +
    "group/" +
    encodeURIComponent(group) +
    "?play=" +
    aptvNextPlayNonce()
  );
}

function aptvCollectionLink(key) {
  return (
    APTV_LINK_PREFIX +
    "collection/" +
    encodeURIComponent(key) +
    "?play=" +
    aptvNextPlayNonce()
  );
}

function aptvParseLink(value) {
  var link = aptvText(value);
  if (link.indexOf(APTV_LINK_PREFIX) !== 0) return null;
  var rest = link.slice(APTV_LINK_PREFIX.length);
  var query = rest.indexOf("?");
  var hash = rest.indexOf("#");
  var cutoff = rest.length;
  if (query >= 0) cutoff = Math.min(cutoff, query);
  if (hash >= 0) cutoff = Math.min(cutoff, hash);
  var path = rest.slice(0, cutoff);
  var slash = path.indexOf("/");
  if (slash < 0) return null;
  var type = path.slice(0, slash);
  var target = path.slice(slash + 1);
  if (type === "channel") {
    if (
      !target ||
      target.length > 1200 ||
      !/^(?:%[0-9A-Fa-f]{2}|[A-Za-z0-9._~!*'()-])+$/.test(target)
    ) {
      return null;
    }
    return { type: type, target: target, raw: link };
  }
  if (type === "group") {
    if (!target || target.length > 1200) return null;
    try {
      target = decodeURIComponent(target);
    } catch (error) {
      return null;
    }
    return { type: type, target: target, raw: link };
  }
  if (type === "collection") {
    if (!target || target.length > 2400) return null;
    try {
      target = decodeURIComponent(target);
    } catch (error) {
      return null;
    }
    return { type: type, target: target, raw: link };
  }
  if (type === "all" && !target) {
    return { type: type, target: "", raw: link };
  }
  return null;
}

function aptvParseChannelToken(value) {
  var token = aptvText(value);
  var parsed = aptvParseLink(token);
  if (parsed && parsed.type === "channel") return parsed;
  if (token.indexOf("aptv-channel:") !== 0) return null;
  var target = token.slice("aptv-channel:".length);
  if (
    !target ||
    target.length > 1200 ||
    !/^(?:%[0-9A-Fa-f]{2}|[A-Za-z0-9._~!*'()-])+$/.test(target)
  ) {
    return null;
  }
  return { type: "channel", target: target, raw: token };
}

function aptvStreamType(url) {
  var value = aptvText(url).split("#")[0].split("?")[0].toLowerCase();
  if (/^rtmp:\/\//.test(value)) return "RTMP";
  if (/^rtsp:\/\//.test(value)) return "RTSP";
  if (/\.m3u8$/.test(value)) return "HLS";
  if (/\.mp4$/.test(value)) return "MP4";
  if (/\.php$/.test(value)) return "动态跳转";
  return "直播流";
}

function aptvChannelHeaders(channel, params) {
  var headers = {
    "User-Agent":
      channel.userAgent ||
      aptvConfiguredDefaultUA(params || {})
  };
  if (channel.referer) headers.Referer = channel.referer;
  return headers;
}

function aptvMapChannel(channel, position, includePlayback) {
  var cover = aptvChannelCover(channel);
  var backdrop = aptvChannelBackdrop(channel);
  var link = aptvChannelLink(channel.key);
  var groupId = aptvGenreId(channel.group);
  var streamType = aptvStreamType(channel.url);
  var item = {
    id: link,
    type: "url",
    title: channel.title,
    originalTitle: channel.name,
    description: [
      channel.group,
      streamType,
      channel.tvgId ? "EPG ID: " + channel.tvgId : ""
    ].filter(Boolean).join(" · "),
    coverUrl: cover,
    posterPath: cover,
    detailPoster: cover,
    backdropPath: backdrop,
    backdropPaths: [backdrop],
    mediaType: "other",
    genreTitle: channel.group,
    genreItems: [{
      id: groupId,
      title: channel.group
    }],
    peoples: [],
    duration: 0,
    isLive: true,
    live: true,
    link: link,
    externalUrl: link,
    playerType: "app"
  };
  if (includePlayback) {
    item.headers = aptvChannelHeaders(channel, {});
    item.customHeaders = item.headers;
  }
  return item;
}

function aptvMapGroup(group) {
  var cover = aptvCover(group.name, group.name);
  var backdrop = aptvBackdrop(group.name);
  var link = aptvGroupLink(group.name);
  var formats = [];
  group.channels.forEach(function (channel) {
    var type = aptvStreamType(channel.url);
    if (formats.indexOf(type) < 0) formats.push(type);
  });
  return {
    id: link,
    type: "url",
    title: group.name,
    originalTitle: group.name,
    description:
      group.channels.length +
      " 个条目 · " +
      formats.join(" / ") +
      " · APTV 公共 M3U",
    coverUrl: cover,
    posterPath: cover,
    detailPoster: cover,
    backdropPath: backdrop,
    backdropPaths: [backdrop],
    mediaType: "other",
    genreTitle: group.name,
    genreItems: [{
      id: aptvGenreId(group.name),
      title: group.name
    }],
    peoples: [],
    duration: 0,
    isLive: true,
    live: true,
    link: link,
    externalUrl: link,
    playerType: "app"
  };
}

function aptvMapCollection(title, channels, key) {
  var first = channels[0] || {};
  var cover = aptvChannelCover(first);
  var backdrop = aptvChannelBackdrop(first);
  var link = aptvCollectionLink(key);
  var formats = [];
  channels.forEach(function (channel) {
    var type = aptvStreamType(channel.url);
    if (formats.indexOf(type) < 0) formats.push(type);
  });
  return {
    id: link,
    type: "url",
    title: title,
    originalTitle: title,
    description:
      channels.length +
      " 个频道 · " +
      formats.join(" / ") +
      " · 进入后选集播放",
    coverUrl: cover,
    posterPath: cover,
    detailPoster: cover,
    backdropPath: backdrop,
    backdropPaths: [backdrop],
    mediaType: "other",
    genreTitle: title,
    genreItems: [],
    peoples: [],
    duration: 0,
    isLive: true,
    live: true,
    link: link,
    externalUrl: link,
    playerType: "app"
  };
}

function aptvFilterByGenre(channels, params) {
  params = params || {};
  var group = aptvGroupFromGenre(params.genreId);
  if (!params.genreId) return channels;
  if (!group) return [];
  return channels.filter(function (channel) {
    return channel.group === group;
  });
}

function aptvSortPreferred(channels, preferred) {
  return channels.slice().sort(function (left, right) {
    var leftIndex = preferred.indexOf(left.title);
    var rightIndex = preferred.indexOf(right.title);
    if (leftIndex < 0) leftIndex = 1000 + left.index;
    if (rightIndex < 0) rightIndex = 1000 + right.index;
    return leftIndex - rightIndex;
  });
}

function aptvFeaturedSpecs(channels) {
  var definitions = [
    {
      key: "featured-cctv",
      title: "央视热门",
      group: "央视IPV4",
      preferred: [
        "CCTV1",
        "CCTV5",
        "CCTV6",
        "CCTV13",
        "CCTV16",
        "CCTV4K",
        "CCTV2",
        "CCTV3"
      ]
    },
    {
      key: "featured-satellite",
      title: "卫视热门",
      group: "卫视IPV4",
      preferred: [
        "湖南卫视",
        "浙江卫视",
        "江苏卫视",
        "东方卫视",
        "北京卫视",
        "凤凰资讯",
        "大湾区卫视",
        "安徽卫视"
      ]
    },
    {
      key: "featured-4k",
      title: "4K/8K 精选",
      group: "4K8K频道",
      preferred: [
        "北京卫视4K",
        "深圳卫视4K",
        "江苏卫视4K",
        "浙江卫视4K",
        "湖南卫视4K",
        "东方卫视4K",
        "广东卫视4K",
        "苏州4K"
      ]
    },
    {
      key: "featured-gala",
      title: "春晚精选",
      group: "历年春晚",
      preferred: [
        "春晚2026",
        "春晚2025",
        "春晚2024",
        "春晚2023",
        "春晚2022",
        "春晚2021"
      ]
    }
  ];
  return definitions.map(function (definition) {
    var pool = channels.filter(function (channel) {
      return channel.group === definition.group;
    });
    var sorted = aptvSortPreferred(pool, definition.preferred);
    return {
      key: definition.key,
      title: definition.title,
      group: definition.group,
      channels: sorted.slice(0, 8)
    };
  }).filter(function (item) {
    return item.channels.length > 0;
  });
}

async function channelGroups(params) {
  try {
    params = params || {};
    var loaded = await aptvLoadPlaylist(params);
    if (params.genreId) {
      var filtered = aptvFilterByGenre(loaded.channels, params);
      if (!filtered.length) return [];
      var genreGroup = aptvGroupFromGenre(params.genreId);
      return [
        aptvMapCollection(
          genreGroup,
          filtered,
          "genre:" + encodeURIComponent(genreGroup)
        )
      ];
    }
    return aptvGroupsFromChannels(loaded.channels).map(aptvMapGroup);
  } catch (error) {
    console.error("[APTV] channelGroups 失败:", error.message || error);
    throw error;
  }
}

async function featuredChannels(params) {
  try {
    params = params || {};
    var loaded = await aptvLoadPlaylist(params);
    var channels = aptvFilterByGenre(loaded.channels, params);
    if (params.genreId) {
      var group = aptvGroupFromGenre(params.genreId);
      if (!channels.length) return [];
      return [
        aptvMapCollection(
          group,
          channels,
          "genre:" + encodeURIComponent(group)
        )
      ];
    }
    return aptvFeaturedSpecs(channels).map(function (spec) {
      return aptvMapCollection(spec.title, spec.channels, spec.key);
    });
  } catch (error) {
    console.error("[APTV] featuredChannels 失败:", error.message || error);
    throw error;
  }
}

async function allChannels(params) {
  try {
    params = params || {};
    var loaded = await aptvLoadPlaylist(params);
    var channels = aptvFilterByGenre(loaded.channels, params);
    if (!channels.length) return [];
    var group = aptvGroupFromGenre(params.genreId);
    var key = group
      ? "genre:" + encodeURIComponent(group)
      : "all";
    return [
      aptvMapCollection(
        group || channels.length + " 个全部条目",
        channels,
        key
      )
    ];
  } catch (error) {
    console.error("[APTV] allChannels 失败:", error.message || error);
    throw error;
  }
}

async function searchChannels(params) {
  try {
    params = params || {};
    var keyword = aptvText(
      params.keyword || params.query || params.title
    ).toLowerCase();
    var page = parseInt(aptvText(params.page) || "1", 10);
    if (!isFinite(page) || page < 1) page = 1;
    var loaded = await aptvLoadPlaylist(params);
    var matched = loaded.channels.filter(function (channel) {
      var haystack = [
        channel.title,
        channel.name,
        channel.group,
        channel.tvgId
      ].join(" ").toLowerCase();
      return !keyword || haystack.indexOf(keyword) >= 0;
    });
    var start = (page - 1) * APTV_SEARCH_PAGE_SIZE;
    var selected = matched.slice(start, start + APTV_SEARCH_PAGE_SIZE);
    if (!selected.length) return [];
    var title = keyword ? "搜索：" + keyword : "全部搜索条目";
    return [
      aptvMapCollection(
        title + " · 第 " + page + " 页",
        selected,
        "search:" + encodeURIComponent(keyword) + ":" + page
      )
    ];
  } catch (error) {
    console.error("[APTV] searchChannels 失败:", error.message || error);
    throw error;
  }
}

async function loadDetail(link) {
  var parsed = aptvParseLink(link);
  if (!parsed) return null;
  try {
    var loaded;
    if (parsed.type === "channel") {
      loaded = await aptvLoadPlaylist({});
      var channel = loaded.channels.find(function (item) {
        return item.key === parsed.target;
      });
      return channel
        ? aptvMapChannel(channel, channel.index, true)
        : null;
    }
    if (parsed.type === "collection") {
      loaded = await aptvLoadPlaylist({});
      var collectionChannels = [];
      var collectionTitle = "频道合集";
      if (parsed.target === "all") {
        collectionChannels = loaded.channels.slice();
        collectionTitle = loaded.channels.length + " 个全部条目";
      } else {
        var featured = aptvFeaturedSpecs(loaded.channels).find(
          function (spec) {
            return spec.key === parsed.target;
          }
        );
        if (featured) {
          collectionChannels = featured.channels;
          collectionTitle = featured.title;
        } else if (parsed.target.indexOf("genre:") === 0) {
          var encodedGroup = parsed.target.slice("genre:".length);
          var genreGroup = "";
          try {
            genreGroup = decodeURIComponent(encodedGroup);
          } catch (error) {}
          collectionChannels = loaded.channels.filter(function (item) {
            return item.group === genreGroup;
          });
          collectionTitle = genreGroup || "频道分类";
        } else if (parsed.target.indexOf("search:") === 0) {
          var searchBody = parsed.target.slice("search:".length);
          var lastColon = searchBody.lastIndexOf(":");
          if (lastColon >= 0) {
            var encodedKeyword = searchBody.slice(0, lastColon);
            var searchPage = parseInt(
              searchBody.slice(lastColon + 1),
              10
            );
            var searchKeyword = "";
            try {
              searchKeyword = decodeURIComponent(encodedKeyword);
            } catch (error) {}
            if (!isFinite(searchPage) || searchPage < 1) searchPage = 1;
            var matched = loaded.channels.filter(function (item) {
              return (
                !searchKeyword ||
                [
                  item.title,
                  item.name,
                  item.group,
                  item.tvgId
                ].join(" ").toLowerCase().indexOf(searchKeyword.toLowerCase()) >= 0
              );
            });
            var start = (searchPage - 1) * APTV_SEARCH_PAGE_SIZE;
            collectionChannels = matched.slice(
              start,
              start + APTV_SEARCH_PAGE_SIZE
            );
            collectionTitle =
              "搜索：" + searchKeyword + " · 第 " + searchPage + " 页";
          }
        }
      }
      if (!collectionChannels.length) return null;
      var collectionDetail = aptvMapCollection(
        collectionTitle,
        collectionChannels,
        parsed.target
      );
      collectionDetail.link = link;
      collectionDetail.episodeItems = collectionChannels.map(
        function (item, index) {
          return aptvMapChannel(item, index, true);
        }
      );
      return collectionDetail;
    }
    if (parsed.type === "group") {
      loaded = await aptvLoadPlaylist({});
      var groupChannels = loaded.channels.filter(function (item) {
        return item.group === parsed.target;
      });
      if (!groupChannels.length) return null;
      var group = {
        name: parsed.target,
        channels: groupChannels
      };
      var detail = aptvMapGroup(group);
      detail.link = link;
      detail.episodeItems = groupChannels.map(function (item, index) {
        return aptvMapChannel(item, index, true);
      });
      return detail;
    }
    if (parsed.type === "all") {
      loaded = await aptvLoadPlaylist({});
      return loaded.channels.map(aptvMapChannel);
    }
    return null;
  } catch (error) {
    console.error("[APTV] loadDetail 失败:", error.message || error);
    throw error;
  }
}

async function loadResource(params) {
  params = params || {};
  var hasLink =
    Object.prototype.hasOwnProperty.call(params, "link") &&
    params.link !== null &&
    params.link !== undefined &&
    aptvText(params.link) !== "";
  var raw = "";
  if (hasLink) {
    raw = params.link;
  } else if (aptvText(params.id)) {
    raw = params.id;
  } else if (aptvText(params.externalUrl)) {
    raw = params.externalUrl;
  } else if (aptvText(params.videoUrl)) {
    raw = params.videoUrl;
  }
  var parsed = aptvParseChannelToken(raw);
  if (!parsed) return [];

  try {
    var loaded = await aptvLoadPlaylist(params);
    var channel = loaded.channels.find(function (item) {
      return item.key === parsed.target;
    });
    if (!channel) {
      throw new Error("频道不存在或直播源已经更新");
    }

    var headers = aptvChannelHeaders(channel, params);
    var streamType = aptvStreamType(channel.url);
    return [{
      name: channel.title + " · APTV",
      description: [
        "来源：Kimentanm/aptv 公共 M3U",
        "分组：" + channel.group,
        "格式：" + streamType,
        "请求头：User-Agent=" + headers["User-Agent"],
        headers.Referer ? "Referer=" + headers.Referer : ""
      ].filter(Boolean).join("\n"),
      url: channel.url,
      duration: 0,
      isLive: true,
      live: true,
      customHeaders: headers,
      headers: headers,
      playerType: "app"
    }];
  } catch (error) {
    console.error("[APTV] loadResource 失败:", error.message || error);
    throw error;
  }
}
